std::map<int, int> m;

// 1. Permissive Access: Inserts if key 1 does not exist
m[1] = 100;

// 2. Safe Read Access: Throws if key 99 missing
try {
    int val = m.at(99);
} catch (const std::out_of_range& e) {
    // Handle missing key
}

// 3. Conditional Insertion (C++17): Inserts only if key 2 is new
// Returns {iterator, bool inserted}
auto [it, inserted] = m.try_emplace(2, 200);

// 4. Checking Existence (Pre-C++20)
if (m.count(3) == 0) {
    m.insert({3, 300});
}

